/* The initial contents of Dino2.exe's tables (.rdata, .data) as C: src/data/
 * (generated by tools/dc2_gendata.py). Each table keeps its original
 * address; Data_Init copies them into the memory image of the standalone
 * builds (in-process the game's own sections are used). */
#ifndef DC2_DATA_H
#define DC2_DATA_H
#include "dc2/types.h"

typedef struct { u32 addr, size; const void *p; } DataBlock;

#define DATA(addr, type, name, n) static const type name[n]
#define DATA_BLOCK(addr, name)    {addr, sizeof name, name}

extern const DataBlock g_rodata[], g_data_game[], g_data_pc[];

/* the tables copied to their addresses (the rest of the image stays zero) */
void Data_Init(void);
/* the blocks one after the other (NULL-terminated list of lists) */
extern const DataBlock *const g_data_lists[];

#endif
